    roleName: "RoleDemo",
    description: "role attach policies",
    maxSessionDuration: 3600,
    trustPolicyDocument: JSON.stringify({
        Statement: [{
            Effect: "Allow",
            Action: ["sts:AssumeRole"],
            Principal: {
                Service: ["auto_scaling"],
            },
        }],
